CREATE TABLE IF NOT EXISTS incidentes_mayores ( id INTEGER PRIMARY KEY AUTOINCREMENT, titulo TEXT NOT NULL, descripcion TEXT, estado TEXT NOT NULL DEFAULT 'ABIERTO' CHECK (estado IN ('ABIERTO', 'MITIGADO', 'RESUELTO', 'CERRADO')), severidad TEXT NOT NULL CHECK (severidad IN ('CRITICA', 'ALTA')), cliente_id TEXT, servicio_id TEXT, responsable_usuario_id INTEGER REFERENCES usuarios (id), abierto_por INTEGER REFERENCES usuarios (id), inicio TEXT NOT NULL, abierto TEXT NOT NULL, mitigado TEXT, resuelto TEXT, cerrado TEXT, causa_raiz TEXT, componente_causa_id INTEGER, resumen_cierre TEXT, origen TEXT NOT NULL DEFAULT 'HELIOS' CHECK (origen IN ('HELIOS', 'IMPORTADO')), actualizado TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS ix_incidentes_mayores_estado ON incidentes_mayores (estado, abierto);
CREATE INDEX IF NOT EXISTS ix_incidentes_mayores_componente ON incidentes_mayores (componente_causa_id, cerrado);
CREATE TABLE IF NOT EXISTS incidente_alertas ( incidente_id INTEGER NOT NULL REFERENCES incidentes_mayores (id), alerta_id TEXT NOT NULL, tipo_alerta TEXT NOT NULL, cliente_id TEXT, servicio_id TEXT, canal_id TEXT, sumada_por INTEGER REFERENCES usuarios (id), sumada TEXT NOT NULL, PRIMARY KEY (incidente_id, alerta_id) ) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS ix_incidente_alertas_alerta ON incidente_alertas (alerta_id);
CREATE TABLE IF NOT EXISTS incidente_tareas ( id INTEGER PRIMARY KEY AUTOINCREMENT, incidente_id INTEGER NOT NULL REFERENCES incidentes_mayores (id), titulo TEXT NOT NULL, detalle TEXT, responsable_usuario_id INTEGER REFERENCES usuarios (id), equipo_id INTEGER REFERENCES equipos (id), componente_id INTEGER, estado TEXT NOT NULL DEFAULT 'PENDIENTE' CHECK (estado IN ('PENDIENTE', 'EN_CURSO', 'HECHA', 'CANCELADA')), resultado TEXT, creada_por INTEGER REFERENCES usuarios (id), creada TEXT NOT NULL, vence TEXT, actualizada TEXT NOT NULL, terminada TEXT, propuesta_por_asistente INTEGER NOT NULL DEFAULT 0 );
CREATE INDEX IF NOT EXISTS ix_incidente_tareas_incidente ON incidente_tareas (incidente_id, estado);
CREATE INDEX IF NOT EXISTS ix_incidente_tareas_responsable ON incidente_tareas (responsable_usuario_id, estado);
CREATE TABLE IF NOT EXISTS incidente_linea_tiempo ( id INTEGER PRIMARY KEY AUTOINCREMENT, incidente_id INTEGER NOT NULL REFERENCES incidentes_mayores (id), fecha TEXT NOT NULL, usuario_id INTEGER REFERENCES usuarios (id), tipo TEXT NOT NULL CHECK (tipo IN ('APERTURA', 'ALERTA_SUMADA', 'ESTADO', 'TAREA', 'NOTA', 'COMUNICADO', 'ESCALAMIENTO', 'CIERRE')), texto TEXT NOT NULL, referencia TEXT );
CREATE INDEX IF NOT EXISTS ix_incidente_linea_tiempo_incidente ON incidente_linea_tiempo (incidente_id, fecha);
CREATE TABLE IF NOT EXISTS componentes_infraestructura ( id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE, tipo TEXT NOT NULL CHECK (tipo IN ('GATEWAY', 'BASE_DE_DATOS', 'AUTENTICACION', 'PROVEEDOR_EXTERNO', 'RED', 'APLICACION')), descripcion TEXT, area_responsable TEXT, equipo_id INTEGER REFERENCES equipos (id), que_revisar TEXT, activo INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS componente_dependencias ( id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id TEXT, servicio_id TEXT, componente_id INTEGER REFERENCES componentes_infraestructura (id), depende_de_componente_id INTEGER NOT NULL REFERENCES componentes_infraestructura (id), CHECK ((servicio_id IS NULL) <> (componente_id IS NULL)) );
CREATE UNIQUE INDEX IF NOT EXISTS ux_componente_dependencias ON componente_dependencias (IFNULL(cliente_id, '*'), IFNULL(servicio_id, ''), IFNULL(componente_id, 0), depende_de_componente_id);
CREATE INDEX IF NOT EXISTS ix_componente_dependencias_servicio ON componente_dependencias (servicio_id, cliente_id);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (1, 'Autenticación', 'AUTENTICACION', 'Ingreso de los usuarios a la app y la web, y códigos de seguridad por SMS.', 'Plataforma', NULL, 'Tasa de ingresos fallidos; demora y entrega de los SMS; certificados vencidos; últimos cambios publicados.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (2, 'Core de cuentas y saldos', 'BASE_DE_DATOS', 'Base de cuentas y saldos: toda operación que mueve dinero la consulta y la actualiza.', 'Base de datos', NULL, 'Tiempo de respuesta de las consultas; conexiones abiertas contra el máximo; bloqueos; espacio en disco; tareas programadas pesadas.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (3, 'Motor de transferencias', 'APLICACION', 'Valida y envía las transferencias entre cuentas propias y hacia otros bancos.', 'Pagos y transferencias', NULL, 'Errores de la aplicación en los registros; cola de transferencias pendientes; último despliegue; respuesta de la red interbancaria.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (4, 'Red interbancaria', 'PROVEEDOR_EXTERNO', 'Red de compensación que conecta con los otros bancos (proveedor externo).', 'Pagos y transferencias', NULL, 'Página de estado del proveedor; rechazos con código de la red; tiempo de respuesta de la red; comunicado del proveedor.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (5, 'Gateway de pagos', 'GATEWAY', 'Recibe los pagos de servicios y los envía al proveedor de cobranza.', 'Pagos y transferencias', NULL, 'Errores 5xx del gateway; tiempo de respuesta; certificados del enlace con el proveedor; uso de CPU y memoria.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (6, 'Proveedor de cobranza de servicios', 'PROVEEDOR_EXTERNO', 'Empresa externa que cobra luz, gas, agua, telefonía e impuestos.', 'Pagos y transferencias', NULL, 'Página de estado del proveedor; rechazos por empresa de servicios; mantenimiento programado; canal de contacto con el proveedor.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (7, 'Proveedor de recargas de celular', 'PROVEEDOR_EXTERNO', 'Integración con las compañías de telefonía para las recargas.', 'Integraciones', NULL, 'Respuesta por compañía de telefonía; saldo prepago con el proveedor; tiempo de respuesta; mantenimiento programado.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (8, 'Proveedor de carga de transporte', 'PROVEEDOR_EXTERNO', 'Integración con el sistema de tarjetas de transporte.', 'Integraciones', NULL, 'Respuesta del sistema de transporte; tiempo de respuesta; promociones activas que suban el tráfico.', 1);
INSERT OR IGNORE INTO componentes_infraestructura (id, nombre, tipo, descripcion, area_responsable, equipo_id, que_revisar, activo) VALUES (9, 'Balanceador y red de entrada', 'RED', 'Punto de entrada de la app, la web y la API: balanceador, firewall y certificados.', 'Infraestructura', NULL, 'Errores 502/503/504; certificados; reglas de firewall cambiadas; tráfico anormal (posible ataque).', 1);
INSERT OR IGNORE INTO componente_dependencias (cliente_id, servicio_id, componente_id, depende_de_componente_id) VALUES (NULL, 'TRANSFERENCIAS', NULL, 1), (NULL, 'TRANSFERENCIAS', NULL, 3), (NULL, 'PAGO_SERVICIOS', NULL, 1), (NULL, 'PAGO_SERVICIOS', NULL, 5), (NULL, 'RECARGA_CELULAR', NULL, 1), (NULL, 'RECARGA_CELULAR', NULL, 7), (NULL, 'RECARGA_TRANSPORTE', NULL, 1), (NULL, 'RECARGA_TRANSPORTE', NULL, 8), (NULL, NULL, 1, 9), (NULL, NULL, 3, 2), (NULL, NULL, 3, 4), (NULL, NULL, 3, 9), (NULL, NULL, 5, 2), (NULL, NULL, 5, 6), (NULL, NULL, 5, 9), (NULL, NULL, 7, 2), (NULL, NULL, 8, 2), ('CLI_006', 'PAGO_SERVICIOS', NULL, 9);
INSERT OR IGNORE INTO incidentes_mayores (id, titulo, descripcion, estado, severidad, cliente_id, servicio_id, responsable_usuario_id, abierto_por, inicio, abierto, mitigado, resuelto, cerrado, causa_raiz, componente_causa_id, resumen_cierre, origen, actualizado) VALUES (1, 'Caída de pagos de servicios de CLI_002', 'No se aprobaba ningún pago de servicios desde la app ni la web.', 'CERRADO', 'CRITICA', 'CLI_002', 'PAGO_SERVICIOS', NULL, NULL, '2026-09-08T14:15:00Z', '2026-09-08T14:20:00Z', '2026-09-08T15:40:00Z', '2026-09-08T16:10:00Z', '2026-09-09T13:00:00Z', 'Certificado vencido en el enlace entre el gateway de pagos y el proveedor de cobranza.', 5, 'Se renovó el certificado y se reinició el gateway. Queda pendiente un aviso automático 30 días antes del vencimiento.', 'IMPORTADO', '2026-09-09T13:00:00Z');
INSERT OR IGNORE INTO incidente_linea_tiempo (id, incidente_id, fecha, usuario_id, tipo, texto, referencia) VALUES (1, 1, '2026-09-08T14:20:00Z', NULL, 'APERTURA', 'Se abrió la sala de crisis: 0 pagos aprobados en CLI_002 desde las 11:15.', NULL), (2, 1, '2026-09-08T14:35:00Z', NULL, 'TAREA', 'Revisar errores del gateway de pagos: el enlace con el proveedor rechaza la conexión.', NULL), (3, 1, '2026-09-08T15:10:00Z', NULL, 'COMUNICADO', 'Se comunicó el incidente al cliente y a Atención al cliente.', NULL), (4, 1, '2026-09-08T15:40:00Z', NULL, 'ESTADO', 'Mitigado: certificado renovado, los pagos vuelven a aprobarse.', NULL), (5, 1, '2026-09-09T13:00:00Z', NULL, 'CIERRE', 'Cerrado con causa raíz: certificado vencido en el enlace con el proveedor de cobranza.', NULL);
INSERT OR IGNORE INTO incidentes_mayores (id, titulo, descripcion, estado, severidad, cliente_id, servicio_id, responsable_usuario_id, abierto_por, inicio, abierto, mitigado, resuelto, cerrado, causa_raiz, componente_causa_id, resumen_cierre, origen, actualizado) VALUES (2, 'Ingreso fallido a la app de CLI_001', 'Los usuarios no podían entrar a la app: el código por SMS no llegaba.', 'CERRADO', 'CRITICA', 'CLI_001', 'TRANSFERENCIAS', NULL, NULL, '2026-09-15T12:00:00Z', '2026-09-15T12:10:00Z', '2026-09-15T13:05:00Z', '2026-09-15T13:30:00Z', '2026-09-16T14:00:00Z', 'El proveedor de SMS cambió la ruta de envío y los códigos de seguridad llegaban con más de 10 minutos de demora.', 1, 'Se pasó a la ruta de respaldo del proveedor de SMS. Se suma una alerta por demora de entrega de los códigos.', 'IMPORTADO', '2026-09-16T14:00:00Z');
INSERT OR IGNORE INTO incidente_linea_tiempo (id, incidente_id, fecha, usuario_id, tipo, texto, referencia) VALUES (6, 2, '2026-09-15T12:10:00Z', NULL, 'APERTURA', 'Se abrió la sala de crisis: cae el tráfico de transferencias de CLI_001 por la app.', NULL), (7, 2, '2026-09-15T12:25:00Z', NULL, 'TAREA', 'Revisar autenticación: los ingresos fallan en el paso del código por SMS.', NULL), (8, 2, '2026-09-15T12:50:00Z', NULL, 'ESCALAMIENTO', 'Se escaló al proveedor de SMS.', NULL), (9, 2, '2026-09-15T13:05:00Z', NULL, 'ESTADO', 'Mitigado: se activó la ruta de respaldo de SMS.', NULL), (10, 2, '2026-09-16T14:00:00Z', NULL, 'CIERRE', 'Cerrado con causa raíz: cambio de ruta del proveedor de SMS.', NULL);
INSERT OR IGNORE INTO incidentes_mayores (id, titulo, descripcion, estado, severidad, cliente_id, servicio_id, responsable_usuario_id, abierto_por, inicio, abierto, mitigado, resuelto, cerrado, causa_raiz, componente_causa_id, resumen_cierre, origen, actualizado) VALUES (3, 'Recargas de celular lentas en CLI_003', 'Las recargas tardaban más de 20 segundos y muchas se rechazaban por tiempo agotado.', 'CERRADO', 'ALTA', 'CLI_003', 'RECARGA_CELULAR', NULL, NULL, '2026-09-22T19:30:00Z', '2026-09-22T19:40:00Z', '2026-09-22T20:45:00Z', '2026-09-22T21:00:00Z', '2026-09-23T15:00:00Z', 'Mantenimiento no avisado del proveedor de recargas en una de las compañías de telefonía.', 7, 'El proveedor terminó el mantenimiento. Se acordó que avise los mantenimientos con 48 horas.', 'IMPORTADO', '2026-09-23T15:00:00Z');
INSERT OR IGNORE INTO incidente_linea_tiempo (id, incidente_id, fecha, usuario_id, tipo, texto, referencia) VALUES (11, 3, '2026-09-22T19:40:00Z', NULL, 'APERTURA', 'Se abrió la sala de crisis: latencia alta en recargas de celular de CLI_003.', NULL), (12, 3, '2026-09-22T20:00:00Z', NULL, 'TAREA', 'Revisar respuesta del proveedor de recargas por compañía de telefonía.', NULL), (13, 3, '2026-09-22T20:45:00Z', NULL, 'ESTADO', 'Mitigado: el proveedor terminó el mantenimiento.', NULL), (14, 3, '2026-09-23T15:00:00Z', NULL, 'CIERRE', 'Cerrado con causa raíz: mantenimiento no avisado del proveedor de recargas.', NULL);
